            return -1
        prefix = [0]
        for s in stones:
            prefix.append(prefix[-1] + s)
        @lru_cache(None)
        def dp(i, j):
            if j - i + 1 < K:
                return 0
            res = 0
            if (j - i) % (K - 1) == 0:
                res = prefix[j+1] - prefix[i]
